assert input() == 'file'
import codecs
events = []
class Key(str):
    __hash__ = str.__hash__
    def __eq__(self, other):
        events.append(other)
        return other == 'file'
    def __str__(self):
        events.append('str')
        return 'shown'
try:
    codecs.EncodedFile(None, **{Key('redirected'): None})
except TypeError as error:
    assert error.args == ("EncodedFile() got multiple values for argument 'shown'",), error.args
else:
    raise AssertionError('duplicate accepted')
assert events == ['file', 'str'], events

print('verified')

assert input() == 'file'
import codecs
events = []
failure = ValueError('truth')
class Decision:
    def __bool__(self):
        events.append('truth')
        raise failure
class Key(str):
    __hash__ = str.__hash__
    def __eq__(self, other):
        events.append(other)
        return Decision()
try:
    codecs.EncodedFile(**{Key('other'): None})
except ValueError as error:
    assert error is failure
else:
    raise AssertionError('truth failure lost')
assert events == ['file', 'truth'], events

print('verified')

